userscript.function:

    		var ckCpnNo = dataOutput.getValue("CHECK_COMPANY");
            if(id == 'CHECK_COMPANY' ){
                var companyCode = formObj.getValue("COMPANY_CODE");
                if(companyCode  == ''){
                    Alert(Sepoa.cache.text.get('AD_102_C_C.MSG01')); // 회사코드를 입력해주세요
                }else{
	                var so = doServiceAjax('sepoa.svc.admin.SepoaOrgManagementService', 'CONNECTION', 'doDuplicateCompany', {COMPANY_CODE:companyCode}, function( so ){
	                    if(so.status != 1){
	                        Alert(Sepoa.cache.text.get("MESSAGE.1049"));
	                        dataOutput.setValue("CHECK_COMPANY","N");
	                        return;
	                    }else{
	                        Alert(Sepoa.cache.text.get("MESSAGE.1050"));
	                        dataOutput.setValue("CHECK_COMPANY","Y");
	                    }
	                });
                }
			}


var title = Sepoa.cache.text.get('AD_102.COMPANY')+' : '+Sepoa.cache.text.get("AD_102.ADD_NEW");
callFunction(['p','p'],'changeHeaderIcon', ['b','show','save']);
callFunction(['p','p'],'changeHeaderIcon', ['b','hide','update,delete']);
callFunction(['p','p'],'changeHeaderText', ['b',title]);
formObj.clear(false);
formObj.setViewMode(false);
dataOutput.setValue("CHECK_COMPANY","N");
formObj.setReadOnly("COMPANY_CODE",false);
btnObj.showButton('NEW,UPDATE,CANCEL,DELETE', false);
btnObj.showButton('SAVE', true); 
formObj.setdisable('CHECK_COMPANY', false);
formObj.showItem('CHECK_COMPANY', true);
formObj.setValue('DEL_FLAG', 1);


		    btnObj.showButton('NEW,SAVE,UPDATE,CANCEL,DELETE', false);

        	switch(id){
                case "SAVE":
                	let result = doSave();
                	if(result == true){
                		formObj.setViewMode( true );
                    	btnObj.showButton('UPDATE', true);
                	} else{
                		formObj.setViewMode(false);
            			btnObj.showButton('SAVE', true); 
                	}
                    break;
                case "UPDATE":
                	formObj.setViewMode( false );
                	formObj.setReadOnly('COMPANY_CODE', true);
					btnObj.showButton('SAVE,CANCEL', true); 
                    break;
                 case "DELETE":
                	formObj.setViewMode( false );
                	btnObj.showButton('SAVE,DELETE,CANCEL', true);
                	doDelete();
                    break;
                case "CANCEL":
                	formObj.setViewMode( true );
                	btnObj.showButton('UPDATE', true);
					btnObj.showButton('SAVE,DELETE,CANCEL', false);                	
                    break;
                case "BACK":
                	doBack();
                	break;        
                default:
                    break;        
            }



        	var result;

        	if(!formObj.validate()){
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }
            if(formObj.getValue('COMPANY_NAME_LOC').length >= 75){
        		Alert("회사명은 75자 이상 넘길 수 없습니다."); 
        		return;
        	}else if(checkPass(formObj.getValue('COMPANY_NAME_ENG'))==false){
        		Alert("회사명(영문)은 영문으로 기입해주세요.");
				return;
        	}else if(checkDate(formObj.getValue('FOUNDATION_DATE'))==false){
        		Alert("설립일은 오늘 이전날짜로 선택해주세요."); 
        		return;
        	}
        	if(dataOutput.getValue('CHECK_COMPANY') !="Y"){
        		Alert("회사코드 중복체크를 해주십시오");
        		return;
        	}

        	var existRCompanyResult = doSelectRCompanyExists();

       		if(existRCompanyResult == true){ // 기존 대표회사가 존재하는 경우
       			result = false;
       			return result;
       		} else if(existRCompanyResult == false){
        		doServiceAjax('sepoa.svc.admin.SepoaOrgManagementService','TRANSACTION','doSaveCompany', null, function( so ){
	                if(so.status == 1){
	                    Alert(Sepoa.cache.text.get("MESSAGE.0001"));
	                    doBack();
	                    callFunction('AD_102_C_G', 'doQuery',[]);
	                }else{
	                    Alert(so.message);
	                }
	            });
	            result = true;
	            return result;
       		}


        	var current_date = new Date();
		    var year = current_date.getFullYear();
		    var month = ("0" + (1 + current_date.getMonth())).slice(-2);
		    var day = ("0" + current_date.getDate()).slice(-2);

        	var toDay = year + month + day;

        	if (date >= toDay) {
                return false;
            }


        Confirm(Sepoa.cache.text.get('MESSAGE.1015'), function(result){
            	if (result) {
	                doServiceAjax('sepoa.svc.admin.SepoaOrgManagementService','TRANSACTION','doDeleteCompany', null, function( so ){
	                    if(so.status == 1){
	                        Alert(Sepoa.cache.text.get("MESSAGE.0001"));
	                        formObj.clear(false);
				            callFunction(['p','p'], 'reloadCells', []); 
	                    }else{
                        	Alert(so.message);
                        	return;
                    	}
                	});
                }
            });


	formObj.setdisable('CHECK_COMPANY', true);
	formObj.setViewMode( true );

    doServiceAjax('sepoa.svc.admin.SepoaOrgManagementService','CONNECTION','doQueryCompany',{COMPANY_CODE : companyCode} ,function( so ){
        if(so.status != 1){
            Alert(so.message);
            return;
        }
        var sf = new SepoaFormater(so.result[0]);
        if(sf.getRowCount() > 0){ 
            formObj.dataMapper(sf);

            if(sf.getArrayMap()[0].REPRESENTATIVE_COMPANY_FLAG == 'Y'){
            	formObj.setValue("REPRESENTATIVE_COMPANY", 1);
            } else{
            	formObj.setValue("REPRESENTATIVE_COMPANY", 0);
            }

             if(sf.getArrayMap()[0].DEL_FLAG == 'Y'){
            	formObj.setValue("DEL_FLAG", 0);
            } else{
            	formObj.setValue("DEL_FLAG", 1);
            }

            dataOutput.setValue("CHECK_COMPANY","Y");
        }else{
        	Alert('조회된회사정보없음') 
        }
       	doQueryEnd();
       	callFunction(['p','p'],'changeHeaderText', ['b',"회사정보"]);
    });


        	// 폼데이터가 있는지 없는지 체크하기위해
        	var formData = formObj.getFormData();
        	var companyCode = formData.COMPANY_CODE;

        	// 버튼초기화
        	btnObj.showButton('NEW,SAVE,UPDATE,CANCEL,DELETE', false);

        	if(companyCode){ // 조회데이터 있을경우
				btnObj.showButton('UPDATE', true);
        	}else {	// 없을경우
        		formObj.setViewMode( true );
	            btnObj.showButton('NEW', true);
        	}


	        var result = false;

			if(formObj.getValue('REPRESENTATIVE_COMPANY')==1){ // 대표회사 여부 선택 시, 이미 대표회사 존재하는 지 확인
	    		doServiceAjax('sepoa.svc.admin.SepoaOrgManagementService','CONNECTION','doSelectRepresentativeCompany', null, function(so){
	    			if(so.status == 2){
						Alert('대표회사가 이미 존재합니다. 기존 대표회사를 해제하고 저장해주세요.');
						result = true;
 					} else if(so.status == 0){
  						Alert(so.message);
  						return;
  					}
	    		}, false);
	     	}
	     	return result;
